// SEO and answer-engine (AEO) helpers: page titles, descriptions, canonical
// links, social cards and structured data (JSON-LD) in one place. The copy is
// written only from what the site itself says, so nothing here promises more
// than the pages deliver.

export const SITE_NAME = "Kasumigaseki MENA";
export const PARENT_NAME = "Kasumigaseki Capital";

/** The branded social card generated by src/app/opengraph-image.tsx (1200 x 630). */
export const DEFAULT_SOCIAL_IMAGE = { url: absoluteUrl("/opengraph-image"), width: 1200, height: 630, alt: `${SITE_NAME}: development, investment and operations across the GCC` };

/** Search results show roughly 60 characters of a title and 155 to 160 of a description. */
export const TITLE_MAX = 60;
export const DESCRIPTION_MAX = 160;

/** Collapse whitespace and cut to at most `max` characters, preferring a sentence end, then a word boundary. */
export function clampDescription(text: string | null | undefined, max = DESCRIPTION_MAX): string {
  const clean = (text ?? "").replace(/\s+/g, " ").trim();
  if (clean.length <= max) return clean;
  const window = clean.slice(0, max);
  const sentenceEnd = Math.max(window.lastIndexOf(". "), window.lastIndexOf("! "), window.lastIndexOf("? "), window.endsWith(".") ? max - 1 : -1);
  if (sentenceEnd >= max * 0.6) return window.slice(0, sentenceEnd + 1);
  const wordEnd = window.lastIndexOf(" ", max - 2);
  return `${window.slice(0, wordEnd > 0 ? wordEnd : max - 1).replace(/[\s.,;:–-]+$/, "")}…`;
}

/** "<title> | Kasumigaseki MENA", unless that would run past what search results show. */
export function withBrand(title: string): string {
  const branded = `${title} | ${SITE_NAME}`;
  return branded.length <= TITLE_MAX ? branded : title;
}

type MetadataInput = {
  title: string;
  description: string;
  /** Root-relative path ("/about-us"); becomes the canonical URL. */
  path: string;
  image?: string | null;
  type?: "website" | "article";
  publishedTime?: string | null;
};

/** Complete metadata for one page: exact title, description, canonical link, Open Graph and Twitter cards. */
export function pageMetadata(input: MetadataInput): Metadata {
  const description = clampDescription(input.description);
  const url = absoluteUrl(input.path);
  const images = [input.image ? { url: mediaUrl(input.image) } : DEFAULT_SOCIAL_IMAGE];
  const isArticle = input.type === "article";
  return {
    title: { absolute: input.title },
    description,
    alternates: { canonical: url },
    openGraph: {
      type: isArticle ? "article" : "website",
      siteName: SITE_NAME,
      locale: "en_AE",
      url,
      title: input.title,
      description,
      images,
      ...(isArticle && input.publishedTime ? { publishedTime: new Date(input.publishedTime).toISOString() } : {}),
    },
    twitter: { card: "summary_large_image", title: input.title, description, images },
  };
}

