export type PageKey = keyof typeof PAGE_SEO;

/** Placeholder values the original seeds left in page rows; treated as "not set" so the curated copy shows. */
const LEGACY_PLACEHOLDERS = new Set([
  "Kasumigaseki MENA",
  "Kasumigaseki MENA is a regional development, investment, and operating platform across the GCC and beyond.",
  "Privacy policy for Kasumigaseki MENA website visitors and enquiry submissions.",
  "Terms and conditions for using the Kasumigaseki MENA website.",
  "Cookie policy for the Kasumigaseki MENA website.",
  "Legal notice and corporate information for the Kasumigaseki MENA website.",
]);

const filled = (value: string | null | undefined) => {
  const clean = (value ?? "").trim();
  return clean && !LEGACY_PLACEHOLDERS.has(clean) ? clean : "";
};

/** The CMS SEO boxes win field by field; empty boxes fall back to the curated copy. */
export function resolvePageSeo(key: PageKey, cms: { title?: string | null; description?: string | null } | null | undefined) {
  const page = PAGE_SEO[key];
  return { ...page, title: filled(cms?.title) || page.title, description: filled(cms?.description) || page.description };
}

// ── Structured data (JSON-LD) ────────────────────────────────────────────────

const CONTEXT = "https://schema.org";

export function organizationJsonLd(settings: SiteSettings) {
  const [street, locality] = settings.address.lines;
  return {
    "@context": CONTEXT,
    "@type": "Organization",
    "@id": ORGANIZATION_ID,
    name: SITE_NAME,
    alternateName: ["Kasumigaseki Capital MENA", "KC MENA"],
    url: SITE_URL,
    logo: mediaUrl("/images/logo kme dark.png"),
    description: PAGE_SEO.home.description,
    email: settings.contact.email,
    telephone: settings.contact.phone,
    address: {
      "@type": "PostalAddress",
      streetAddress: street,
      addressLocality: locality?.split(",")[0]?.trim() || "Dubai",
      addressCountry: "AE",
    },
    areaServed: ["United Arab Emirates", "GCC"],
    parentOrganization: { "@type": "Organization", name: PARENT_NAME, url: settings.links.corporate },
    sameAs: [settings.links.linkedin].filter(Boolean),
  };
}

export function websiteJsonLd() {
  return {
    "@context": CONTEXT,
    "@type": "WebSite",
    "@id": WEBSITE_ID,
    url: SITE_URL,
    name: SITE_NAME,
    inLanguage: "en",
    publisher: { "@id": ORGANIZATION_ID },
  };
}

export type Crumb = { name: string; path: string };

export function breadcrumbJsonLd(crumbs: Crumb[]) {
  return {
    "@context": CONTEXT,
    "@type": "BreadcrumbList",
    itemListElement: crumbs.map((crumb, index) => ({ "@type": "ListItem", position: index + 1, name: crumb.name, item: absoluteUrl(crumb.path) })),
  };
}

type WebPageKind = "WebPage" | "AboutPage" | "ContactPage" | "CollectionPage" | "FAQPage";

export function webPageJsonLd(input: { kind?: WebPageKind; name: string; description: string; path: string }) {
  return {
    "@context": CONTEXT,
    "@type": input.kind ?? "WebPage",
    "@id": `${absoluteUrl(input.path)}#webpage`,
    url: absoluteUrl(input.path),
    name: input.name,
    description: clampDescription(input.description),
    inLanguage: "en",
    isPartOf: { "@id": WEBSITE_ID },
    about: { "@id": ORGANIZATION_ID },
  };
}

/** WebPage + BreadcrumbList for one of the fixed pages, from its resolved SEO copy. */
export function fixedPageJsonLd(key: PageKey, seo: { title: string; description: string }, kind?: WebPageKind) {
  const page = PAGE_SEO[key];
  const crumbs: Crumb[] = key === "home" ? [{ name: "Home", path: "/" }] : [{ name: "Home", path: "/" }, { name: page.name, path: page.path }];
  return [webPageJsonLd({ kind, name: seo.title, description: seo.description, path: page.path }), breadcrumbJsonLd(crumbs)];
}

type NewsPostLike = { slug: string; title: string; excerpt?: string | null; cover_image?: string | null; published_at?: string | Date | null; updated_at?: string | Date | null };

export function newsArticleJsonLd(post: NewsPostLike) {
  const url = absoluteUrl(`/news/${post.slug}`);
  const published = post.published_at ? new Date(post.published_at).toISOString() : undefined;
  const modified = post.updated_at ? new Date(post.updated_at).toISOString() : published;
  return {
    "@context": CONTEXT,
    "@type": "NewsArticle",
    "@id": `${url}#article`,
    mainEntityOfPage: url,
    url,
    headline: post.title.slice(0, 110),
    ...(post.excerpt ? { description: clampDescription(post.excerpt) } : {}),
    ...(post.cover_image ? { image: [mediaUrl(post.cover_image)] } : {}),
    ...(published ? { datePublished: published } : {}),
    ...(modified ? { dateModified: modified } : {}),
    inLanguage: "en",
    author: { "@id": ORGANIZATION_ID },
    publisher: { "@id": ORGANIZATION_ID },
  };
}

/** Plain text from a stored answer (which may contain simple HTML). */
export function plainText(html: string): string {
  return html
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+/g, " ")
    .trim();
}

export function faqPageJsonLd(faqs: { question: string; answer: string }[]) {
  return {
    "@context": CONTEXT,
    "@type": "FAQPage",
    "@id": `${absoluteUrl("/faq")}#faq`,
    mainEntity: faqs.map((faq) => ({ "@type": "Question", name: faq.question, acceptedAnswer: { "@type": "Answer", text: plainText(faq.answer) } })),
  };
}
